def get_neighbors(grid, r, c):
    rows, cols = len(grid), len(grid[0])
    neighs = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                neighs.append(grid[nr][nc])
    return neighs

