from collections import deque

def count_connected_regions(grid, val=None):
    """Count connected regions with same value"""
    H, W = len(grid), len(grid[0])
    visited = set()

    def bfs(start_r, start_c):
        region = []
        queue = deque([(start_r, start_c)])
        visited.add((start_r, start_c))
        while queue:
            r, c = queue.popleft()
            region.append((r,c))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < H and 0 <= nc < W:
                    if (nr, nc) not in visited:
                        if val is None or grid[nr][nc] == grid[r][c]:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
        return region

    regions = []
    for r in range(H):
        for c in range(W):
            if (r, c) in visited or grid[r][c] == 0:
                continue
            region = bfs(r, c)
            if val is None or grid[r][c] == val:
                regions.append(region)
    return regions

