# Look for runs of identical values
def find_runs(grid):
    runs = []
    for r in range(len(grid)):
        prev = None
        run_start = 0
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val == 0:
                continue
            if prev is not None and prev != val:
                runs.append(('row', r, (run_start, c), prev))
            prev = val
            run_start = c
    return runs

