# Count frequency of most common non-zero value
def most_common_nonzero(grid):
    counts = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val > 0:
                counts[val] = counts.get(val, 0) + 1
    return max(counts, key=counts.get), counts.get(max(counts, key=counts.get), 0), counts

