def map_grid_to_output_method(grid, method="floor"):
    """Try different ways to map 7x7 to 3x3"""
    H, W = len(grid), len(grid[0])

    if method == "floor":
        # Simple floor division
        out = [[0]*3 for _ in range(3)]
        for r in range(H):
            for c in range(W):
                r_out = r // 3
                c_out = c // 3
                if grid[r][c] != 0:
                    out[r_out][c_out] = max(out[r_out][c_out], grid[r][c])
        return out

    elif method == "center_of_block":
        # Each output cell corresponds to center block of input
        out = [[0]*3 for _ in range(3)]
        for i in range(3):
            for j in range(3):
                # Center position in each region
                r_center = i * 2 + 1
                c_center = j * 2 + 1
                if r_center < H and c_center < W:
                    val = grid[r_center][c_center]
                    if val != 0:
                        out[i][j] = val
        return out

    elif method == "max_in_region":
        out = [[0]*3 for _ in range(3)]
        for i in range(3):
            for j in range(3):
                # Define region boundaries
                r_start = i * 2  # 0, 2, 4
                r_end = min((i+1)*2, H)
                c_start = j * 2  # 0, 2, 4
                c_end = min((j+1)*2, W)

                if r_end > r_start and c_end > c_start:
                    vals = [grid[r][c] for r in range(r_start, r_end) for c in range(c_start, c_end) if grid[r][c] != 0]
                    if vals:
                        out[i][j] = max(vals)
        return out

    return None

