# Check connected component theory - maybe outputs mark where components cluster
from collections import deque, Counter

def count_components(grid):
    H, W = len(grid), len(grid[0])
    visited = set()

    def bfs(val, start_r, start_c):
        queue = deque([(start_r, start_c)])
        visited.add((start_r, start_c))
        size = 0
        while queue:
            r, c = queue.popleft()
            size += 1
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < H and 0 <= nc < W:
                    if (nr, nc) not in visited and grid[nr][nc] == val:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
        return size

    total = 0
    comp_sizes = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and (r,c) not in visited:
                sz = bfs(grid[r][c], r, c)
                comp_sizes.append(sz)
                total += sz

    return comp_sizes, total

for name, grid in [("Demo1", demo1_input), ("Demo2", demo2_input), ("Demo3", demo3_input), ("Test", test_input)]:
    comps, total = count_components(grid)
    print(f"{name}: {len(comps)} components, total non-zeros={total}")

